{
  "items": [
    {
      "name": "ContinuousAt.eventually_lt",
      "module_name": "Mathlib.Topology.Order.OrderClosed",
      "kind": "theorem",
      "type": "∀ {α : Type u} {β : Type v} [inst : TopologicalSpace α] [inst_1 : LinearOrder α] [OrderClosedTopology α] {f g : β → α}\n  [inst_3 : TopologicalSpace β] {x₀ : β},\n  ContinuousAt f x₀ → ContinuousAt g x₀ → f x₀ < g x₀ → ∀ᶠ (x : β) in nhds x₀, f x < g x"
    },
    {
      "name": "lt_subset_interior_le",
      "module_name": "Mathlib.Topology.Order.OrderClosed",
      "kind": "theorem",
      "type": "∀ {α : Type u} {β : Type v} [inst : TopologicalSpace α] [inst_1 : LinearOrder α] [OrderClosedTopology α] {f g : β → α}\n  [inst_3 : TopologicalSpace β], Continuous f → Continuous g → {b | f b < g b} ⊆ interior {b | f b ≤ g b}"
    },
    {
      "name": "intervalIntegral.integral_lt_integral_of_continuousOn_of_le_of_exists_lt",
      "module_name": "Mathlib.MeasureTheory.Integral.IntervalIntegral.Basic",
      "kind": "theorem",
      "type": "∀ {f g : ℝ → ℝ} {a b : ℝ},\n  a < b →\n    ContinuousOn f (Set.Icc a b) →\n      ContinuousOn g (Set.Icc a b) →\n        (∀ x ∈ Set.Ioc a b, f x ≤ g x) →\n          (∃ c ∈ Set.Icc a b, f c < g c) → ∫ (x : ℝ) in a..b, f x < ∫ (x : ℝ) in a..b, g x"
    },
    {
      "name": "UniformSpace.ofDist_aux",
      "module_name": "Mathlib.Topology.MetricSpace.Pseudo.Defs",
      "kind": "theorem",
      "type": "∀ (ε : ℝ), 0 < ε → ∃ δ > 0, ∀ x < δ, ∀ y < δ, x + y < ε"
    },
    {
      "name": "ContinuousMap.modulus",
      "module_name": "Mathlib.Topology.ContinuousMap.Compact",
      "kind": "definition",
      "type": "{α : Type u_1} →\n  {β : Type u_2} →\n    [inst : PseudoMetricSpace α] → [CompactSpace α] → [inst_2 : PseudoMetricSpace β] → C(α, β) → (ε : ℝ) → 0 < ε → ℝ"
    },
    {
      "name": "IsCompact.lt_sInf_iff_of_continuous",
      "module_name": "Mathlib.Topology.Order.Compact",
      "kind": "theorem",
      "type": "∀ {α : Type u_2} {β : Type u_3} [inst : ConditionallyCompleteLinearOrder α] [inst_1 : TopologicalSpace α]\n  [inst_2 : TopologicalSpace β] [ClosedIicTopology α] {f : β → α} {K : Set β},\n  IsCompact K → K.Nonempty → ContinuousOn f K → ∀ (y : α), y < sInf (f '' K) ↔ ∀ x ∈ K, y < f x"
    }
  ]
}

